 "content": "def transform(grid):
    """Complete a periodic field of parallel NW-SE diagonal stripes."""
    h, w = len(grid), len(grid[0])
    stripes = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                d = c - r
                if d in stripes and stripes[d] != value:
                    raise ValueError("non-constant diagonal")
                stripes[d] = value

    # The visible diagonal stripes encode one repeating cycle. Choose the
    # shortest cycle that assigns a consistent color to every observed stripe.
    period = None
    for p in range(1, h + w + 1):
        residues = {}
        for d, value in stripes.items():
            k = d % p
            if k in residues and residues[k] != value:
                break
            residues[k] = value
        else:
            period = p
            palette = residues
            break
    if period is None:
        raise ValueError("could not infer diagonal period")

    return [[palette[(c-r) % period] for c in range(w)] for r in range(h)]
